INSERT OR REPLACE INTO bills (id, title, description, category, author_id, author_name, party_id, yes_votes, no_votes, status, impact_summary) VALUES ('bill-tax-reform', 'RUU Pajak Karbon & Insentif Hilirisasi Nikel', 'Mengenakan pajak karbon progresif pada pabrik smelter luar negeri dan memberikan insentif 20% bagi industri hilirisasi domestik di Morowali & Weda Bay.', 'Ekonomi & Tambang', 'usr-satria', '', 'pdin', 0, 0, 'voting', '');
INSERT OR REPLACE INTO bills (id, title, description, category, author_id, author_name, party_id, yes_votes, no_votes, status, impact_summary) VALUES ('bill-military-radar', 'RUU Peningkatan Anggaran Radar Pertahanan ZEE Natuna & Papua', 'Mengalokasikan tambahan 15% dari APBN untuk pemasangan sistem radar pertahanan maritim generasi ke-5 serta pangkalan kapal selam di Natuna dan Sorong.', 'Pertahanan & Kedaulatan', 'usr-satria', '', 'pdin', 0, 0, 'voting', '');
INSERT OR REPLACE INTO bills (id, title, description, category, author_id, author_name, party_id, yes_votes, no_votes, status, impact_summary) VALUES ('bill-subsidy-umkm', 'RUU Bantuan Tunai & Subsidi Pupuk Petani Desa', 'Menjamin ketersediaan pupuk bersubsidi 100% dan pinjaman lunak bunga 0% untuk 12 juta keluarga petani di Jawa, Sumatera, dan Nusa Tenggara.', 'Kesejahteraan Sosial', 'usr-satria', '', 'pdin', 0, 0, 'voting', '');

