-- 7. DATA KORAN PERS NASIONAL
INSERT OR REPLACE INTO articles (id, title, content, category, author_id, author_name, author_title, newspaper_name, views, upvotes) VALUES ('art-1', '', 'Gedung Nusantara DPR RI bergemuruh saat fraksi oposisi mempertanyakan lonjakan anggaran belanja radar pertahanan. Sementara itu, kubu pemerintah menegaskan bahwa kedaulatan laut nusantara tidak dapat dikompromikan.', 'Parlemen', 'usr-satria', 'Redaksi Harian Garuda', '', 'Harian Nusantara', 100, 840);
INSERT OR REPLACE INTO articles (id, title, content, category, author_id, author_name, author_title, newspaper_name, views, upvotes) VALUES ('art-2', '', 'Kementerian Perindustrian mengumumkan surplus perdagangan kuartal ini didorong oleh 14 smelter baru yang beroperasi penuh di Morowali dan Weda Bay. Partai Teknokrat mendorong dividen diarahkan untuk beasiswa riset.', 'Ekonomi', 'usr-satria', 'Warta Ekonomi Republik', '', 'Harian Nusantara', 100, 620);
INSERT OR REPLACE INTO articles (id, title, content, category, author_id, author_name, author_title, newspaper_name, views, upvotes) VALUES ('art-3', '', 'Simulasi Pilpres terbaru menunjukkan elektabilitas tiga poros utama masih berada di rentang 28% - 35%. Suara pemilih di Jawa Tengah, Jawa Barat, dan Jawa Timur diprediksi menjadi medan tempur penentu kemenangan mutlak.', 'Pemilu', 'usr-satria', 'Lembaga Indikator Politik Nusantara', '', 'Harian Nusantara', 100, 1950);

